    """Acquire tokens by logging in."""
    log("Acquiring tokens...")

    # Check if tokens file exists
    if os.path.exists(TOKENS_FILE):
        existing = load_tokens()
        if existing and 'access_token' in existing:
            log(f"Warning: {TOKENS_FILE} already exists. Remove it first or use --force flag.")
            return

    # Login
    data = {'username': 'admin', 'password': 'password123'}
    result, status = make_request('POST', '/auth/login', data)

    if status != 200:
        log(f"Failed to acquire tokens: {result}")
        return

    # Save tokens
    tokens = {
        'access_token': result['access_token'],
        'refresh_token': result['refresh_token'],
        'acquired_at': datetime.utcnow().isoformat(),
        'expires_in': result.get('expires_in', 900)
    }
    save_tokens(tokens)

    log(f"Tokens acquired successfully!")
    log(f"Access token: {tokens['access_token'][:50]}...")
    log(f"Refresh token: {tokens['refresh_token'][:50]}...")
    log(f"Tokens saved to {TOKENS_FILE}")

