        return

    access_token = tokens['access_token']
    headers = {'Authorization': f'Bearer {access_token}'}

    result, status = make_request('GET', '/auth/validate', headers=headers)

    if status == 200:
        log("Token is valid!")
        log(f"Subject: {result.get('sub')}")
        log(f"JTI: {result.get('jti')}")
        log(f"Expires at: {datetime.fromtimestamp(result.get('exp')).isoformat()}")
    elif status == 401:
        log("Token is invalid or expired!")
    elif status == 403:
        log("Token has been revoked!")
    else:
        log(f"Validation failed with status {status}: {result}")

